import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2020-01-14 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2020-01-14 :: Crimson SeaStor OSD Weekly Meeting","date":"2020-01-14T00:00:00.000Z","updated":"2020-01-16T00:00:00.000Z","tags":["Ceph","B+树","异步版本","B+树实现","事务处理","写放大","Ceph存储系统","OSD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-01-14_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2020/2020-01-14_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),a={name:"posts/2020/2020-01-14_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function r(n,l,s,_,p,u){return i(),t("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph存储系统的B+树异步版本开发</strong></p><ul><li>Sammy正在重构B+树的实现，并尝试开发异步版本。</li><li>讨论了B+树与DoStore的集成，特别是关于键值布局、指针和地址处理的细节。</li></ul></li><li><p><strong>B+树的物理和逻辑地址处理</strong></p><ul><li>需要至少两个版本的B+树实现：一个物理地址处理，一个逻辑地址处理。</li><li>讨论了B+树的灵活性和适应性问题，以及如何处理不同版本的B+树实现。</li></ul></li><li><p><strong>Ceph存储系统的设计和实现</strong></p><ul><li>讨论了从零开始实现B+树的可行性，以及如何基于现有设计进行定制化开发。</li><li>强调了避免I/O操作，确保实现纯粹基于内存或功能性的设计。</li></ul></li><li><p><strong>事务处理和写放大问题</strong></p><ul><li>讨论了如何在同一事务中处理B+树更新和其他操作，以及如何减少写放大问题。</li><li>强调了事务处理的复杂性和对整体系统设计的影响。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ol><li><p><strong>B+树的实现策略</strong></p><ul><li>决定从零开始实现B+树，但会参考Petri设计，并进行高度定制化。</li><li>确定了不使用外部库，而是自行开发B+树实现，以更好地适应Ceph的特定需求。</li></ul></li><li><p><strong>事务处理和写放大问题的解决方案</strong></p><ul><li>确定了在事务处理中集成B+树更新的策略，以及如何通过优化设计和缓存管理减少写放大问题。</li><li>讨论了持久内存的使用，以及如何通过逻辑地址管理进一步优化写放大问题。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><p><strong>B+树的开发和测试</strong></p><ul><li>Sammy将继续开发B+树的实现，并定期更新团队进展。</li><li>团队成员将参与代码审查和测试，确保实现符合预期。</li></ul></li><li><p><strong>事务处理和写放大问题的进一步研究</strong></p><ul><li>将继续研究和优化事务处理机制，确保系统在高负载下的稳定性和性能。</li><li>将探索持久内存的使用，以及如何通过逻辑地址管理进一步优化写放大问题。</li></ul></li><li><p><strong>团队协作和任务分配</strong></p><ul><li>团队将根据项目进展和需求，适时分配任务和资源，确保项目按计划推进。</li><li>将持续关注Ceph存储系统的性能和稳定性，及时调整开发策略和方向。</li></ul></li></ol><p>通过本次会议，团队对Ceph存储系统的B+树实现和事务处理机制有了更深入的理解，并制定了明确的开发和优化计划。</p>',8)])])}const g=e(a,[["render",r]]);export{h as __pageData,g as default};
